<template><div><el-card><template #header><div class="header"><span>统一收件箱</span><el-button @click="load">刷新</el-button></div></template><el-input v-model="content" type="textarea" :rows="4" maxlength="5000" show-word-limit placeholder="一句话记录任务、提醒、消费、学习笔记或普通想法……"/><div class="submit"><el-button type="primary" :loading="saving" @click="submit">分析并加入收件箱</el-button></div></el-card><el-card><el-table :data="items"><el-table-column label="时间" width="180"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column><el-table-column prop="content" label="原始内容" min-width="280"/><el-table-column label="建议" width="130"><template #default="{row}"><el-tag>{{typeName(row.suggestedType)}} {{Math.round(row.confidence*100)}}%</el-tag></template></el-table-column><el-table-column prop="reason" label="识别原因"/><el-table-column label="确认类型" width="170"><template #default="{row}"><el-select :model-value="row.confirmedType||row.suggestedType" @change="onConfirm(row.id,$event)"><el-option v-for="type in types" :key="type.value" :label="type.label" :value="type.value"/></el-select></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="danger" @click="archive(row.id)">归档</el-button></template></el-table-column></el-table><el-empty v-if="!items.length" description="收件箱已清空"/></el-card></div></template>
<script setup lang="ts">import{ElMessage}from'element-plus';import{onMounted,ref}from'vue';import{archiveInbox,confirmInbox,createInbox,listInbox,type InboxItem}from'@/api/productivity';const content=ref(''),saving=ref(false),items=ref<InboxItem[]>([]),types=[{label:'任务',value:'TASK'},{label:'提醒',value:'REMINDER'},{label:'消费',value:'EXPENSE'},{label:'学习',value:'LEARNING'},{label:'普通记录',value:'NOTE'}];async function load(){items.value=(await listInbox('PENDING')).data;}async function submit(){if(!content.value.trim())return;saving.value=true;try{const item=(await createInbox(content.value)).data;ElMessage.success(`建议分类：${typeName(item.suggestedType)}`);content.value='';await load();}finally{saving.value=false;}}function onConfirm(id:number,value:unknown){void confirm(id,String(value));}async function confirm(id:number,type:string){await confirmInbox(id,type);ElMessage.success('分类已确认，原文已保留');await load();}async function archive(id:number){await archiveInbox(id);await load();}const typeName=(value:string)=>types.find(v=>v.value===value)?.label||value;const time=(value:string)=>new Date(value).toLocaleString('zh-CN',{hour12:false});onMounted(load);</script>
<style scoped>.header{display:flex;justify-content:space-between;align-items:center}.submit{text-align:right;margin-top:12px}.el-card+.el-card{margin-top:16px}</style>
